        const info = tpInfoFor(apiSymbol());
        if (!mcOnTick(plan.price, info.tick)) return { err: at ? 'The price is off the tick grid' : 'The book price is off the tick grid' };
        const ref = mcMidRef();
        const bad = mcSanity(q, ref, info.tick);
        if (bad) return { err: bad };
