        const named = { Backquote: '`', Minus: '-', Equal: '=', BracketLeft: '[', BracketRight: ']', Backslash: '\\', Semicolon: ';', Quote: '\'',
            Comma: ',', Period: '.', Slash: '/', IntlBackslash: '§' };
