    const pkIco = (k, cls, n) => `<svg class="${cls || 'pk-ic'}"${n ? ` style="width:${n}px;height:${n}px"` : ''} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PK_IC[k] || ''}</svg>`;
