    cuLog('you', 'test run (REAL orders) on ' + sym + ' size ' + size + ': ' + (yes ? 'started' : 'cancelled'), { control: 'test-run', yes, market: sym, size });
    if (!yes) { msg.textContent = 'Cancelled.'; return; }
