        const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
        const a = cuEl('a', { href: url, download: 'better-vest-copy-log-' + new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-') + '.json' });
        document.body.appendChild(a);
