async function cwSetupApply(start) {
    const st = CW.setup;
    const m = cuCurrent();
    if (!st || !st.lead) return;
    const ids = Array.from(st.picked);
    const rule = st.rule;
    cuLog('you', () => 'copier setup: ' + (start ? 'Save and start' : 'Save') + ' (' + (st.mode === 'new' ? 'new group' : 'group ' + st.gid) + ', ' + ids.length + ' followers, ' + CW_RULES[rule].word + ')', { control: 'setup-apply', start: !!start, rule, n: ids.length });
    if (m.demo) {
        if (st.mode === 'new') { cuNote('This is the demo. Nothing is changed.'); cwSetupClose(); return; }
        if (String(st.lead) !== String(m.leaderId || '')) cuOnLeader({ target: { value: String(st.lead) } });
        cwMembers(m).forEach((r) => { const want = st.picked.has(String(r.accountId)); if (!!r.on !== want) cuDemoAct('follower', r.accountId, want); });
        ids.forEach((id) => cuDemoAct('ratio', id, rule === 'custom' ? st.ratios[id] || 1 : 1));
        cuDemoAct('sizeBy', rule === 'match');
        cwSetupClose();
        if (start) await cwMaster(true);
        return;
    }
    let gid = st.gid;
    if (st.mode === 'new') {
        let r = null;
        try { r = cpNewGroup(st.lead, ids); } catch (x) { r = { ok: false, why: cuMsg(x) }; }
        cuLog('you', () => 'New group: ' + (r && r.ok ? 'created ' + r.id : 'refused (' + (r && r.why) + ')'), () => ({ control: 'new-group', ok: !!(r && r.ok), leader: st.lead, followers: ids }));
        if (!r || !r.ok) { cuNote((r && r.why) || 'Could not create the group.'); return; }
        gid = r.id;
        CU.gsel = r.id;
        CU.sig.leader = '';
        try { if (typeof cpSetFocus === 'function') cpSetFocus(r.id); } catch (x) {}
    } else {
        if (String(st.lead) !== String(m.leaderId || '')) {
            cuOnLeader({ target: { value: String(st.lead) } });
            if (String(cuCurrent().leaderId || '') !== String(st.lead)) return;
            CU.sig.leader = '';
        }
        const now = cuCurrent();
        for (const r of cwMembers(now)) { const id = String(r.accountId); if (r.on && !st.picked.has(id)) await cwFollowerOn(id, false); }
        for (const id of ids) { const r = now.rows.find((x) => String(x.accountId) === id); if (!r || !r.on) await cwFollowerOn(id, true); }
    }
    ids.forEach((id) => { const want = rule === 'custom' ? st.ratios[id] || 1 : 1; const r = cuCurrent().rows.find((x) => String(x.accountId) === id); if (!r || Number(r.ratio) !== want) cuEditFollower(id, { ratio: want }); });
    try { if (typeof cpSetSizeBy === 'function') cpSetSizeBy(rule === 'match' ? 'account' : 'ratio', gid); } catch (x) { cuNote('Could not set the size rule: ' + cuMsg(x)); } /*! This file is part of Better Vest by Astral and is protected by copyright. ref bv-07689fde */
    CW.setup = null;
    CW.sig = {};
    CW.fitFor = '';
    if (st.mode === 'new' && !start) cuNote('Group ' + gid + ' is ready, switched off. Switch copying on when you are ready to trade ' + cwName(st.lead) + '.');
    cuRender();
    if (start) await cwMaster(true);
}

